"""Render the generated analysis JSON as review tables (addresses only, no firmware bytes)."""
import argparse,json,collections
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--dir',type=Path,required=True);p.add_argument('--out-dir',type=Path,required=True);a=p.parse_args()
 J=lambda n:json.loads((a.dir/n).read_text())
 inv,mt,cs,ks,pr,tr,fs=J('inventory.json'),J('match.json'),J('constants.json'),J('keys.json'),J('profile.draft.json'),J('translate_dryrun.json'),J('free_space.json')
 a.out_dir.mkdir(parents=True,exist_ok=True)
 L=['# Generated: hook table 1.6.1 -> 1.6.8','','Generated by tools/port/run_analysis.sh from %s (%s). Do not edit by hand.'%(inv['label'],inv['sha256'][:16]),'',
    'guard: same-bytes = 1.6.8 original bytes identical; relocated-bytes = identical modulo branch/pointer relocation (guard must be re-derived); different-bytes / no-site = manual port.','',
    '| 1.6.1 | size | 1.6.8 | match | guard | status | purpose |','|---|---|---|---|---|---|---|']
 for h in pr['hooks']:L.append('| %s | %d | %s | %s | %s | %s | %s |'%(h['old'],h['size'],h['new'] or '-',h['conf'],h['guard'],h['status'],h['reason'][:90].replace('|','/')))
 (a.out_dir/'HOOKS.md').write_text('\n'.join(L)+'\n')
 L=['# Generated: native dependencies 1.6.1 -> 1.6.8','','Do not edit by hand. Status auto = accepted by evidence; review = located, needs a human check; unresolved = manual port.','',
    '## Counts','','```',json.dumps(pr['counts'],indent=1),'```','',
    '## Flash (functions, return addresses, tables) that are not auto','','| 1.6.1 | 1.6.8 | match | identical part of function | used by |','|---|---|---|---|---|']
 for k,e in sorted(mt['flash'].items()):
  st=pr['flash'][k]['status']
  if st=='auto':continue
  L.append('| %s | %s | %s | %s | %s |'%(k,e.get('new') or '-',e['conf'],e.get('function',{}).get('identical_fraction','-'),', '.join((e.get('source') or e.get('sites'))[:2]).replace('|','/')))
 L+=['','## RAM','','| 1.6.1 | 1.6.8 | evidence | how |','|---|---|---|---|']
 for k,e in sorted(mt['ram'].items()):L.append('| %s | %s | %s | %s |'%(k,e.get('new') or '-',e['conf'],e['how'][:110]))
 L+=['','## Parameter keys (registry alignment)','','registry add: %s -> %s; registrations %s'%(ks['registry_add']['old'],ks['registry_add']['new'],ks['registrations']),'',pr['param_keys']['rule'],'','Non-equal registration regions:','']
 for c in ks['changes']:L.append('- %s: %s -> %s'%(c['tag'],c['old'],c['new']))
 L+=['','## UI / action ids','',pr['ui_ids']['rule'],'','## Constants used by Playground whose native uses changed (evidence)','','| constant | verdict | evidence | example | used by |','|---|---|---|---|---|']
 for k,v in sorted(cs['constants'].items(),key=lambda x:int(x[0],16)):
  if v['verdict'] in ('changed','mixed','split-changed','split-mixed'):L.append('| %s | %s | %s %s | %s | %s |'%(k,v['verdict'],v['evidence'],v.get('split_new_values') or '',(v['changed_examples'] or ['-'])[0],', '.join(v['source'][:2])))
 L+=['','## Translator dry run (source tokens)','','```',json.dumps(tr['stats'],indent=1),'```']
 (a.out_dir/'DEPENDENCIES.md').write_text('\n'.join(L)+'\n')
 L=['# Generated: 1.6.8 free space and cave homes','','```',json.dumps(dict(stock_end=fs['stock_end'],m7_end=fs['m7_end'],free=fs['free'],budget=fs['budget']),indent=1),'```','',
    'Native zero runs inside 1.6.8 code/data (NOT usable without proof; Diagnostics 2.0 broke icons this way):','',', '.join('%s..%s'%(x,y) for x,y,_ in fs['native_zero_runs_not_usable']),'',
    '| 1.6.1 range | size | payload | 1.6.8 | content |','|---|---|---|---|---|']
 for h in fs['homes']:L.append('| %s..%s | %d | %d | %s | %s |'%(h['old'][0],h['old'][1],h['size'],h['payload'],h['status'],h['reason'][:80].replace('|','/')))
 (a.out_dir/'FREE_SPACE.md').write_text('\n'.join(L)+'\n')
 print('docs written to',a.out_dir)
if __name__=='__main__':main()
